'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({format:'sq-field-survey',version:1,meshQuantityUnit:'m',project:{name:'農地圍籬勘查',client:'',phone:'',address:'',date:new Date().toLocaleDateString('sv-SE')},conditions:{ground:'一般土壤',access:'小貨車可達',slope:'平坦',demolition:'不需拆除',boundary:'待確認',utilities:'待確認'},notes:'',photos:[],segments:[seg(20,0),seg(12,90),{...seg(4,0),type:'gate',gate:'double'}],rates:{mesh:180,post:650,rail:100,plate:250,buried:500,direct:0,gate:12000,labor:350},pricing:{extra:0,discount:0,tax:5,excavatorShifts:0,excavatorRate:0,excavatorTransport:0}});
function seg(length=10,turn=0){return{id:'seg-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),length,turn,type:'fence',height:1.8,spacing:2,wire:3.4,mesh:50,meshChoice:'2英吋',excavator:'待確認',meshMat:'galv',base:'buried',depth:.5,railCount:2,postDia:60.5,gate:'double',angle:0,note:''}}
const meshOptions={'2英吋':50,'3英吋':75,'4英吋':100,'正2英吋':50.8};
function migrate(x){if(x?.format!=='sq-field-survey'||!Array.isArray(x.segments))return x;x.photos??=[];for(const s of x.segments){s.id??=seg().id;s.meshChoice??=Object.keys(meshOptions).find(k=>meshOptions[k]===s.mesh)||('原資料 '+s.mesh+' mm');s.excavator??='待確認'}if(x.rates)x.rates.direct??=0;if(x.pricing){x.pricing.excavatorShifts??=0;x.pricing.excavatorRate??=0;x.pricing.excavatorTransport??=0}x.meshQuantityUnit='m';return x}
let applied=null,appliedSource='',studioLoaded=false,deletedSegment=null,previewTimer=null,previewSignature='';
let data=fresh();try{const x=localStorage.getItem('sq-field-survey-v1');if(x)data=validate(migrate(JSON.parse(x)))}catch{}
function validatePhotos(photos){if(!Array.isArray(photos)||photos.length>20)throw Error('每案最多20張照片');const ids=new Set();for(const p of photos){if(!p||typeof p.id!=='string'||! /^[a-zA-Z0-9_-]{1,100}$/.test(p.id)||ids.has(p.id))throw Error('照片識別資料不正確');ids.add(p.id);for(const [key,max]of [['name',180],['caption',500],['segmentId',100]])if(typeof p[key]!=='string'||p[key].length>max)throw Error('照片文字資料不正確');if(p.dataUrl!==undefined&&(typeof p.dataUrl!=='string'||p.dataUrl.length>480000||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.dataUrl)))throw Error('照片格式不正確')}return photos}
function validate(x){if(x?.format!=='sq-field-survey'||x.version!==1||!x.project||!x.conditions||!x.rates||!x.pricing||!Array.isArray(x.segments)||!x.segments.length||x.segments.length>200)throw Error('不是本版勘查資料，或段數超過 200');const segmentIds=new Set();for(const s of x.segments){if(typeof s.id!=='string'||! /^[a-zA-Z0-9_-]{1,100}$/.test(s.id)||segmentIds.has(s.id))throw Error('路段識別資料不正確');segmentIds.add(s.id);for(const [k,a,b]of [['length',.5,5000],['height',.5,6],['spacing',.5,6],['turn',-180,180],['depth',.1,2],['wire',1,6],['mesh',25,150],['railCount',0,4],['postDia',25,200],['angle',0,110]])if(!Number.isFinite(s[k])||s[k]<a||s[k]>b)throw Error(k+' 數值超出範圍');for(const[k,v]of [['type',['fence','gate']],['base',['plate','buried','direct']],['meshMat',['galv','highgalv','pvc']],['gate',['single','double']]])if(!v.includes(s[k]))throw Error('規格選項錯誤')}for(const v of [...Object.values(x.rates),...Object.values(x.pricing)])if(!Number.isFinite(v)||v<0||v>1e7)throw Error('金額設定不正確');for(const k of ['excavatorShifts','excavatorRate','excavatorTransport'])if(!Number.isFinite(x.pricing[k])||x.pricing[k]<0||x.pricing[k]>1e7)throw Error('怪手估價數值不正確');if(x.pricing.excavatorShifts>1000)throw Error('怪手台班數上限1000');if(x.pricing.tax>100||String(x.notes).length>20000)throw Error('資料超出範圍');if(x.segments.reduce((n,s)=>n+s.length,0)>20000)throw Error('本測試版單案總長上限 20,000 公尺');validatePhotos(x.photos||[]);return x}
function field(label,key,value,options,min,max,step){return `<label>${label}${options?`<select data-key="${key}">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:`<input data-key="${key}" value="${esc(value)}" type="${min!==undefined?'number':key==='date'?'date':'text'}" ${min!==undefined?`min="${min}" max="${max}" step="${step||'any'}"`:''}>`}</label>`}
function blankDesign(){const next=fresh();next.project.name='新圍籬勘查';next.segments=[seg()];return next}
function insertSegment(type='fence',after=data.segments.length-1){if(data.segments.length>=200)throw Error('最多 200 段');const template=(type==='fence'?data.segments.find(s=>s.type==='fence'):data.segments.findLast(s=>s.type==='fence'))||seg();const next={...structuredClone(template),id:seg().id,length:type==='gate'?4:template.length,turn:0,type,angle:0,note:'',gate:'double'};if(type==='gate')next.postDia=Math.max(89.1,next.postDia);data.segments.splice(after+1,0,next);return after+1}
function removeSegment(index){if(data.segments.length<=1)throw Error('至少保留一段，請使用新設計開始另一案');deletedSegment={index,segment:structuredClone(data.segments[index])};data.segments.splice(index,1)}
function restoreSegment(){if(!deletedSegment)return false;if(data.segments.length>=200)throw Error('最多 200 段');data.segments.splice(Math.min(deletedSegment.index,data.segments.length),0,deletedSegment.segment);deletedSegment=null;return true}
function resetScene(){applied=null;appliedSource='';deletedSegment=null;clearTimeout(previewTimer)}
function backupAndReplace(next){validate(next);localStorage.setItem('sq-field-survey-previous',JSON.stringify(data));data=next;resetScene();render()}
function render(){window.photoLibrary?.render(); $('project').innerHTML=Object.entries({name:'案件名稱',client:'客戶稱呼',phone:'聯絡電話',address:'施工地址',date:'勘查日期'}).map(([k,l])=>field(l,k,data.project[k])).join('');$('conditions').innerHTML=Object.entries({ground:['地面',['一般土壤','混凝土','碎石','岩盤','待確認']],access:['進場條件',['小貨車可達','大貨車可達','僅人力搬運','待確認']],slope:['地形',['平坦','緩坡','階梯落差','待確認']],demolition:['既有圍籬',['不需拆除','需拆除清運','待確認']],boundary:['界址',['已確認','待確認']],utilities:['地下管線',['已確認位置','待確認']]}).map(([k,[l,o]])=>field(l,k,data.conditions[k],o)).join('');$('notes').value=data.notes;$('undoDelete').disabled=!deletedSegment;try{$('restorePrevious').hidden=!localStorage.getItem('sq-field-survey-previous')}catch{$('restorePrevious').hidden=true}
$('segments').innerHTML=data.segments.map((s,i)=>`<div class="segment" data-index="${i}"><div class="between"><b>${String(i+1).padStart(2,'0')} · ${s.type==='gate'?'大門':'菱形網圍籬'}</b><button data-remove="${i}" ${data.segments.length===1?'disabled':''}>移除此段</button></div><div class="grid">${field('類型','type',s.type,[['fence','菱形網圍籬'],['gate','大門']])}${field('柱心長度 m','length',s.length,null,.5,5000)}${field(i?'相對前段轉角 °（左正右負）':'起始方向 °','turn',s.turn,null,-180,180,.1)}${field('高度 m','height',s.height,[1.2,1.5,1.8,2,2.4,3])}${field('最大柱距 m','spacing',s.spacing,[1,1.5,2,2.5,3])}${field('立柱外徑 mm','postDia',s.postDia,[42.7,48.6,60.5,76.3,89.1,101.6])}${field('網線徑 mm','wire',s.wire,[2.6,3,3.4,4,5])}${field('網目','meshChoice',s.meshChoice,[...Object.keys(meshOptions),...(!meshOptions[s.meshChoice]?[s.meshChoice]:[])])}${field('網材質','meshMat',s.meshMat,[['galv','鍍鋅'],['highgalv','高鍍鋅'],['pvc','PVC 包覆（綠）']])}${field('橫桿排數','railCount',s.railCount,[0,1,2,3,4])}${field('基礎工法','base',s.base,[['buried','埋入／混凝土'],['direct','單獨埋入'],['plate','底板固定']])}${field('埋深 cm（50 起）','depth',Number((s.depth*100).toFixed(2)),null,50,200,5)}${s.type==='gate'?field('門型','gate',s.gate,[['single','單開'],['double','雙開']])+field('門開啟角度 °','angle',s.angle,[0,45,90,110]):''}</div><div class="turns">${field('常用方向／彎折角度','turn',s.turn,[[150,'左轉 150°'],[135,'左轉 135°'],[120,'左轉 120°'],[90,'左轉 90°'],[60,'左轉 60°'],[45,'左轉 45°'],[30,'左轉 30°'],[15,'左轉 15°'],[0,'直行 0°'],[-15,'右轉 15°'],[-30,'右轉 30°'],[-45,'右轉 45°'],[-60,'右轉 60°'],[-90,'右轉 90°'],[-120,'右轉 120°'],[-135,'右轉 135°'],[-150,'右轉 150°'],[180,'左迴轉 180°'],[-180,'右迴轉 180°'],...(![0,15,30,45,60,90,120,135,150,180].includes(Math.abs(s.turn))?[[s.turn,'自訂 '+s.turn+'°']]:[])])}<button type="button" data-turn="45">左轉45°</button><button type="button" data-turn="90">左轉90°</button><button type="button" data-turn="-45">右轉45°</button><button type="button" data-turn="-90">右轉90°</button></div><p class="muted">${i?'相對前一段，左正右負':'第一段為起始方向，0°向東、90°向北'}；也可在上方數字欄輸入 −180°～180°，支援小數。</p><label>此段備註<textarea data-key="note" rows="2">${esc(s.note)}</textarea></label><div class="segmentActions"><button type="button" class="primary" data-insert-fence="${i}" aria-label="在第 ${i+1} 段下方新增圍籬">＋ 在下方新增圍籬</button><button type="button" data-insert-gate="${i}">＋ 在此段後新增大門</button></div></div>`).join('');
$('pricing').innerHTML=field('雜項／運費／拆除 NT$','extra',data.pricing.extra,null,0,1e7)+field('折讓 NT$','discount',data.pricing.discount,null,0,1e7)+field('稅率 %','tax',data.pricing.tax,[0,5]);update()}
function design(){let heading=0;const nodes=[{x:0,z:0}],edges=[];for(const [i,s]of data.segments.entries()){heading+=s.turn*Math.PI/180;const a=nodes.at(-1);nodes.push({x:a.x+Math.cos(heading)*s.length,z:a.z-Math.sin(heading)*s.length});edges.push({...s,a:i,b:i+1,style:s.type==='gate'?'gate':'clamp',postDia:s.type==='gate'?Math.max(89.1,s.postDia):s.postDia,thickness:2,railShape:'round',railDia:30,material:'galv',basePreset:'15',baseSize:15,topFix:'through',meshColor:'green',direction:1,brace:true,gateType:s.gate})}return{format:'sq-fence-design',version:1,name:data.project.name.slice(0,60),nodes,edges}}
function estimate(){let mesh=0,rail=0,total=0,gates=0;const posts=new Map(),d=design();function add(x,z,s,gate=false){const k=x.toFixed(4)+','+z.toFixed(4);if(!posts.has(k))posts.set(k,{base:s.base,gate});else if(gate)posts.get(k).gate=true}for(const[i,s]of data.segments.entries()){total+=s.length;const a=d.nodes[i],b=d.nodes[i+1];add(a.x,a.z,s,s.type==='gate');add(b.x,b.z,s,s.type==='gate');if(s.type==='gate'){gates++;continue}mesh+=s.length;rail+=s.length*s.railCount;const spans=Math.ceil((s.length-1e-8)/s.spacing);for(let n=1;n<spans;n++)add(a.x+(b.x-a.x)*n/spans,a.z+(b.z-a.z)*n/spans,s)}const plate=[...posts.values()].filter(p=>p.base==='plate').length,direct=[...posts.values()].filter(p=>p.base==='direct').length;return{total,posts:posts.size,mesh,rail,gates,plate,direct,buried:posts.size-plate-direct}}
const names={mesh:['菱形網（按長度）','m'],post:['立柱（含門柱）','支'],rail:['橫桿','m'],plate:['底板固定基礎','處'],buried:['埋入／混凝土基礎','處'],direct:['單獨埋入（請填單價）','處'],gate:['門組（含門片）','組'],labor:['安裝工資','m']};
function lines(){const q=estimate();return Object.entries(names).map(([k,[name,unit]])=>({key:k,name,unit,qty:({post:q.posts,gate:q.gates,labor:q.total})[k]??q[k],rate:data.rates[k]})).concat([{key:'excavatorWork',name:'怪手施工費',unit:'台班',qty:data.pricing.excavatorShifts,rate:data.pricing.excavatorRate,manual:true},{key:'excavatorTransport',name:'怪手進退場費',unit:'式',qty:1,rate:data.pricing.excavatorTransport,manual:true}])}
function quote(){const items=lines(),subtotal=items.reduce((n,l)=>n+l.qty*l.rate,0)+data.pricing.extra,net=Math.max(0,subtotal-data.pricing.discount),tax=Math.round(net*data.pricing.tax/100);return{items,excavatorSubtotal:data.pricing.excavatorShifts*data.pricing.excavatorRate+data.pricing.excavatorTransport,subtotal,net,tax,total:net+tax}}
function money(n){return Math.round(n).toLocaleString('zh-TW')}
function update(){const q=estimate();$('metrics').innerHTML=[['總長（含門）',q.total.toFixed(1),'m'],['菱形網長度',q.mesh.toFixed(1),'m'],['立柱',q.posts,'支'],['大門',q.gates,'組']].map(([l,n,u])=>`<div class="metric">${l}<b>${n}</b>${u}</div>`).join('');$('bill').innerHTML=lines().map(l=>`<tr><td>${l.name}</td><td>${l.qty.toFixed(2)} ${l.unit}</td><td><input aria-label="${l.name}每${l.unit}單價" data-rate="${l.key}" type="number" min="0" max="10000000" value="${l.rate}" ${l.manual?'disabled':''}><small>元／${l.unit}</small></td><td>${money(l.qty*l.rate)}</td></tr>`).join('');$('excavatorPricing').innerHTML=field('預估台班數（可填0.5）','excavatorShifts',data.pricing.excavatorShifts,null,0,1000,.5)+field('每台班單價 NT$','excavatorRate',data.pricing.excavatorRate,null,0,1e7)+field('進退場費合計 NT$','excavatorTransport',data.pricing.excavatorTransport,null,0,1e7);const equipment=quote();$('excavatorSummary').textContent='怪手費用小計 NT$ '+money(equipment.excavatorSubtotal);const {subtotal,net,tax}=equipment;$('totals').innerHTML=`未稅小計 NT$ ${money(subtotal)}<br>折讓 NT$ ${money(data.pricing.discount)} · 稅額 NT$ ${money(tax)}<br><strong>試算總額 NT$ ${money(net+tax)}</strong>${data.pricing.discount>subtotal?'<p class="warning">折讓超過小計，計稅基礎以 0 計。</p>':''}`;try{localStorage.setItem('sq-field-survey-v1',JSON.stringify(data));$('status').textContent='已自動儲存在本機'}catch{$('status').textContent='無法本機儲存，請匯出備份'}$('applyStatus').textContent=applied?(appliedSource===JSON.stringify(data)?'目前配置已確認':'示意圖已隨表單更新，修改後尚未確認'):'示意圖即時預覽，尚未確認配置';schedulePreview()}
function notice(t){$('notice').textContent=t;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',4000)}
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.key,r=el.dataset.rate;if(!k&&!r)return;const prev=structuredClone(data);try{if(el.validity&&!el.validity.valid)throw Error('請輸入欄位範圍內的數值');const box=el.closest('.segment');if(r)data.rates[r]=Number(el.value);else if(box){const s=data.segments[Number(box.dataset.index)];s[k]=k==='depth'?Number(el.value)/100:typeof s[k]==='number'?Number(el.value):el.value}else{const obj=el.closest('#project')?data.project:el.closest('#conditions')?data.conditions:data.pricing;obj[k]=typeof obj[k]==='number'?Number(el.value):el.value}if(k==='meshChoice')data.segments[Number(box.dataset.index)].mesh=meshOptions[el.value]??data.segments[Number(box.dataset.index)].mesh;if(k==='depth'&&Number(el.value)<50)throw Error('埋深至少 50 公分');validate(data);if(k==='type'||k==='turn')render();else update()}catch(err){data=prev;render();notice(err.message)}});
$('notes').addEventListener('input',()=>{data.notes=$('notes').value;update()});
function showSegment(index){document.querySelector('[data-index="'+index+'"]')?.scrollIntoView({behavior:'smooth',block:'start'})}
$('segments').addEventListener('click',e=>{try{const fence=e.target.closest('[data-insert-fence]');if(fence){const index=insertSegment('fence',Number(fence.dataset.insertFence));render();showSegment(index);return}const insert=e.target.closest('[data-insert-gate]');if(insert){const index=insertSegment('gate',Number(insert.dataset.insertGate));render();showSegment(index);return}const turn=e.target.closest('[data-turn]');if(turn){const i=Number(turn.closest('.segment').dataset.index);data.segments[i].turn=Number(turn.dataset.turn);render();return}const b=e.target.closest('[data-remove]');if(b){removeSegment(Number(b.dataset.remove));render();notice('已移除，可按「復原刪除」加回')}}catch(err){notice(err.message)}});
$('add').onclick=()=>{try{const i=insertSegment();render();showSegment(i)}catch(e){notice(e.message)}};
$('addGate').onclick=()=>{try{const i=insertSegment('gate');render();showSegment(i)}catch(e){notice(e.message)}};
$('undoDelete').onclick=()=>{try{const i=deletedSegment?.index;if(restoreSegment()){render();showSegment(Math.min(i,data.segments.length-1));notice('已復原刪除的段落')}}catch(e){notice(e.message)}};
let pendingDesign=null;
function askDesign(next,label,message){pendingDesign=next;$('designDialogMessage').textContent=message;$('designConfirm').textContent=label;$('designDialog').showModal()}
$('newDesign').onclick=()=>askDesign(blankDesign(),'備份並建立新設計','目前案件會先備份在本機，可用「取回上一案」恢復。重要案件也請匯出 JSON 保存。');
$('restorePrevious').onclick=()=>{try{const saved=localStorage.getItem('sq-field-survey-previous');if(!saved)return notice('沒有上一案備份');askDesign(validate(migrate(JSON.parse(saved))),'交換並取回上一案','取回上一案後，目前案件會交換保存為上一案備份。')}catch(e){notice('無法取回：'+e.message)}};
$('designCancel').onclick=()=>{$('designDialog').close();pendingDesign=null};
$('designConfirm').onclick=()=>{if(!pendingDesign)return;try{backupAndReplace(pendingDesign);pendingDesign=null;$('designDialog').close();window.scrollTo({top:0,behavior:'smooth'});notice('已切換設計，原案件已備份在本機')}catch(e){notice('尚未切換：無法保存本機備份，請先匯出目前案件。')}};
function sendPreview(){if(studioLoaded){const current=design(),signature=JSON.stringify(current);if(signature!==previewSignature){$('studio').contentWindow.postMessage({type:'sq-survey-design',design:current},location.origin);previewSignature=signature}$('emptyScene').hidden=true}}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{if(!$('studio').getAttribute('src'))$('studio').src='studio.html?embed=1';else sendPreview()},250)}
$('studio').onload=()=>{studioLoaded=true;previewSignature='';sendPreview()};
$('openStudio').onclick=()=>{try{validate(data);if(data.segments.some(s=>s.base!=='plate'&&s.depth<.5))throw Error('請先將埋深修正為至少 50 公分');const transfer=design();transfer.edges=transfer.edges.map(({note,excavator,...edge})=>edge);const token=window.surveyStudioBridge.save(localStorage,transfer);location.assign('studio.html?survey='+encodeURIComponent(token))}catch(e){notice('尚未帶入：'+e.message)}};
$('apply').onclick=()=>{try{validate(data);if(data.segments.some(s=>s.base!=='plate'&&s.depth<.5))throw Error('舊資料含未滿 50 公分的埋深，請先逐段修正');applied=structuredClone(design());appliedSource=JSON.stringify(data);if(!$('studio').getAttribute('src'))$('studio').src='studio.html?embed=1';else sendPreview();$('emptyScene').hidden=true;update();notice('已確認目前配置，示意圖仍會隨表單更新')}catch(e){notice(e.message)}};
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('studio').contentWindow&&e.data?.type==='sq-survey-error'){$('status').textContent='圖面超出工具範圍';notice(e.data.message)}});
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
